package com.cpf.starter.notification.sms.spi;import com.cpf.starter.notification.*;public final class CpfSmsNotificationAdapter implements CpfNotificationProvider {private final CpfSmsDispatcher dispatcher;public CpfSmsNotificationAdapter(CpfSmsDispatcher d){dispatcher=d;}public String channel(){return "SMS";}public CpfNotificationResult send(CpfNotificationRequest r){var x=dispatcher.send(r.recipient(),r.variables().getOrDefault("body",""),r.idempotencyKey());return new CpfNotificationResult(r.notificationId(),"SMS",x.status(),x.providerMessageId(),x.detail(),java.time.Instant.now());}}
